import React from "react";

const MaterialPage = () => {
  const materiais = [
    {
      id: 1,
      titulo: "Guia de Liderança",
      tipo: "Arquivo PDF",
      tamanho: "2,3 MB",
      icone: "https://cdn-icons-png.flaticon.com/512/337/337946.png",
      corBotao: "bg-[#B95758] hover:bg-[#e14d3a]",
    },
    {
      id: 2,
      titulo: "Slides – Aula 02",
      tipo: "Apresentação",
      tamanho: "1,5 MB",
      icone: "https://cdn-icons-png.flaticon.com/512/337/337946.png",
      corBotao: "bg-[#B95758] hover:bg-[#e14d3a]",
    },
    {
      id: 3,
      titulo: "Checklist de Atividades",
      tipo: "Excel",
      tamanho: "800 KB",
      icone: "https://cdn-icons-png.flaticon.com/512/732/732220.png",
      corBotao: "bg-green-600 hover:bg-green-700",
    },
  ];

  return (
    <main className="flex min-h-screen bg-[#FAF9F7] font-[Poppins,sans-serif]">
      {/* Painel lateral */}
      <aside className="w-72 bg-gradient-to-b from-[#B95758] to-[#e14d3a] text-white p-6 flex flex-col justify-between">
        <div>
          <h2 className="text-lg font-bold mb-6 uppercase">Módulos</h2>
          <ul className="space-y-3 text-sm">
            <li className="hover:text-yellow-200 cursor-pointer">Aula 01 – Bem Vindo</li>
            <li className="hover:text-yellow-200 cursor-pointer">Aula 02 – Liderança</li>
            <li className="hover:text-yellow-200 cursor-pointer">Aula 03 – Desenvolvimento</li>
            <li className="hover:text-yellow-200 cursor-pointer">Aula 04 – Propósito</li>
            <li className="hover:text-yellow-200 cursor-pointer">Aula 05 – Estilos</li>
            <li className="hover:text-yellow-200 cursor-pointer">Aula 06 – Bônus</li>
          </ul>
        </div>

        <button className="w-full bg-white text-[#B95758] font-semibold py-2 rounded-md hover:bg-gray-100 transition">
          Material de Apoio
        </button>
      </aside>

      {/* Conteúdo principal */}
      <section className="flex-1 p-10">
        <h1 className="text-3xl font-bold text-center mb-10">
          📚 Materiais de Apoio – Formação em Liderança
        </h1>

        {/* Grid de materiais */}
        <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-6 max-w-6xl mx-auto">
          {materiais.map((material) => (
            <div
              key={material.id}
              className="bg-white shadow-lg rounded-xl p-6 flex flex-col items-center text-center hover:shadow-xl transition duration-300"
            >
              <img
                src={material.icone}
                alt={material.titulo}
                className="w-20 mb-4"
              />
              <h3 className="font-semibold text-gray-800 mb-2">{material.titulo}</h3>
              <p className="text-gray-500 text-sm mb-4">
                {material.tipo} • {material.tamanho}
              </p>
              <button
                className={`${material.corBotao} text-white px-5 py-2 rounded-lg font-medium transition duration-300`}
              >
                Baixar
              </button>
            </div>
          ))}
        </div>
      </section>
    </main>
  );
};

export default MaterialPage;
